export function localizedGuides(locale: Locale): Guide[] {
  if (locale === "en") return guides;
  const labels = copy[locale];
  const slugs = ["what-is-an-iban", "how-to-validate-an-iban", "what-is-a-bic-swift-code", "what-is-sepa", "how-italian-iban-works", "how-to-find-abi-and-cab", "iban-vs-bic"];
  const bySlug = new Map(slugs.map((slug, index) => [slug, editions[locale][index]]));
  const categories: Record<string, string> = { "The essentials": labels.essentials, "Validation": labels.validation, "Bank identifiers": labels.bankIdentifiers, "Payments explained": labels.payments, "Country guide": labels.countryGuide };
  return guides.map(guide => {
    const edition = bySlug.get(guide.slug);
    if (!edition) throw new Error(`Missing editorial translation: ${locale}/${guide.slug}`);
    return { ...guide, ...edition, category: categories[guide.category] ?? guide.category, readTime: labels.readTime, sources: guide.sources.map(source => localizeSource(source, locale)), tool: { ...guide.tool, label: labels.tryTool } };
  });
}

