export function localizedCountryNotes(country: Country, locale: Locale, name: string): string {
  if (locale === "en") return country.notes;
  return nationalNotes[locale][country.code] ?? interpolate(copy[locale].nationalFormat, { country: name, code: country.code, length: country.length, format: country.format });
}
